Q: How to spawn object around a specific point with specific radius in Unity2D using C# A: <p>I know this was answered a long time ago, but I was shocked to see the unnecessarily high complexity of the top answer. A much simpler solution is this:</p>
<pre><code>Instantiate(enemyPrefab, SetSpawnPos(),  Quaternion.identity);

Vector3 SetSpawnPos()
{

    float randomX = Random.Range(-1f, 1f);
    float randomZ = Random.Range(-1f, 1f);

    &quot;For a 2D game, simply use a Vector2 instead&quot;
    var dir = new Vector3(randomizeX, 0, randomizeZ).normalized;

    var spawnPos = (dir * spawnDistance);

    return spawnPos;

}
</code></pre>
<p>All this does is find random values for the x and y direction, plug them into a vector, normalize the result, and then multiply that by distance (aka the circle radius) to get a spawn position.</p>

Q: API Handling on Google Apps Script is not using API key A: <p>I found the answer after some research. Here is the revised code if someone gets the same issue.</p>
<pre><code>const POINT_IDS = [&quot;8271&quot;, &quot;8272&quot;];
const BASE_URL = &quot;https://api-management-opendata-production.azure-api.net/api/datasets/stibmivb/rt/WaitingTimes/&quot;;
const API_KEY = &quot;YOUR-API-KEY&quot;;
const CACHE_KEY = &quot;stib_arrivals&quot;;

function doGet(e) {
  if (e &amp;&amp; e.parameter &amp;&amp; e.parameter.data === &quot;1&quot;) {
    // Serve from cache — fast, always available
    const cache = CacheService.getScriptCache();
    const cached = cache.get(CACHE_KEY);
    const data = cached || &quot;[]&quot;;
    return ContentService
      .createTextOutput(data)
      .setMimeType(ContentService.MimeType.JSON);
  } else {
    return HtmlService.createTemplateFromFile(&quot;Page&quot;).evaluate()
      .setXFrameOptionsMode(HtmlService.XFrameOptionsMode.ALLOWALL);
  }
}

// This function is called by the time-based trigger, NOT by the page
function refreshCache() {
  const allArrivals = [];
  const cache = CacheService.getScriptCache();

  for (const pointId of POINT_IDS) {
    const url = `${BASE_URL}?where=pointid=%22${pointId}%22`;

    let response;
    try {
      response = UrlFetchApp.fetch(url, {
        method: &quot;get&quot;,
        headers: {
          &quot;Cache-Control&quot;: &quot;no-cache&quot;,
          &quot;bmc-partner-key&quot;: API_KEY
        },
        muteHttpExceptions: true
      });
    } catch (err) {
      Logger.log(`Fetch error ${pointId}: ${err.message}`);
      continue;
    }

    Logger.log(`HTTP ${response.getResponseCode()} ${pointId}`);
    Logger.log(response.getContentText());

    if (response.getResponseCode() !== 200) {
      continue;
    }

    let json;
    try {
      json = JSON.parse(response.getContentText());
    } catch (err) {
      Logger.log(`JSON parse error ${pointId}: ${err.message}`);
      continue;
    }

    const records = json.results || [];
    for (const record of records) {
      let times;
      try {
        const clean = record.passingtimes.replace(/\\\&quot;/g, '&quot;');
        times = JSON.parse(clean);
      } catch (err) {
        Logger.log(`passingtimes error ${pointId}: ${err.message}`);
        continue;
      }

      for (const pt of times) {
        if (!pt?.destination) continue;
        allArrivals.push({
          line: pt.lineId || &quot;?&quot;,
          dest: pt.destination.fr || pt.destination.nl || &quot;—&quot;,
          arrival: pt.expectedArrivalTime,
          pointid: pointId
        });
      }
    }
  }

  Logger.log(`Cached ${allArrivals.length} arrivals`);
  cache.put(CACHE_KEY, JSON.stringify(allArrivals), 120);
}
</code></pre>

Q: Can I get TalkBack to read Arabic text in my mostly English app when the device language is set to English? A: <p>Create an <code>AnnotatedString</code> text and set the <code>LocaleList</code> of a <code>SpanStyle</code> surrounding the text you want to read in a specific language:</p>
<pre class="lang-kotlin prettyprint-override"><code>val text = &quot;مرحبا&quot;
val arabicText = remember(text) {
    buildAnnotatedString {
        withStyle(SpanStyle(localeList = LocaleList(&quot;ar&quot;))) {
            append(text)
        }
    }
}
Text(text = arabicText)
</code></pre>

Q: How to convert double to string without the power to 10 representation (E-05) A: <p>For this case useful custom <code>Strict Decimal Format</code> which allows to avoid undesirable behavior of standard formats (like padding with trailing zeros, limited precision, exponential notation)</p>
<pre><code>string StrictDecimalFormat = &quot;0.&quot; + new string('#', 339); 

/* repeat # up to 339 times for showing of smallest possible values: 0.######... */
</code></pre>
<p>Note about rounding from <a href="https://stackoverflow.com/a/1658420/6627992">an answer</a>:</p>
<blockquote>
<p>.NET will always round a double to 15 significant decimal digits before applying your formatting, regardless of the precision requested by your format and regardless of the exact decimal value of the binary number.</p>
</blockquote>
<p><a href="https://sharplab.io/#v2:" rel="nofollow noreferrer">Playground</a></p>
<pre><code>using System;
/*
using System.Globalization;

string DecimalSeparator = CultureInfo.CurrentCulture.NumberFormat.NumberDecimalSeparator;
string StrictDecimalFormat = &quot;0&quot; + DecimalSeparator + new string('#', 339);
*/

string StrictDecimalFormat = &quot;0.&quot; + new string('#', 339);

Console.WriteLine(0.00000123456789.ToString());
//                1.23456789E-06
Console.WriteLine(0.00000123456789.ToString(&quot;F20&quot;));
//                0.00000123456789000000
Console.WriteLine(0.00000123456789.ToString(StrictDecimalFormat));
//                0.00000123456789


/* fixed point formats has limited precision and may show unpredictable tail digits */

Console.WriteLine(0.1234567890123456789.ToString(&quot;F20&quot;));
//                0.12345678901234567737
Console.WriteLine(0.01234567890123456789.ToString(&quot;F20&quot;));
//                0.01234567890123456843
Console.WriteLine(0.001234567890123456789.ToString(&quot;F20&quot;));
//                0.00123456789012345671

/* only 15 significant digits possible with accurate rounding for strict decimal format */

Console.WriteLine(0.1234567890123456789.ToString(StrictDecimalFormat));
//                0.123456789012346
Console.WriteLine(0.0000000001234567890123456789.ToString(StrictDecimalFormat));
//                0.000000000123456789012346
</code></pre>

